import "./state-of-tic-tac-toe" for StateOfTicTacToe
import "wren-testie/testie" for Testie, Expect

Testie.test("StateOfTicTacToe") { |do, skip|
  do.test("Won games -> Finished game where X won via left column victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "XOO",
      "X  ",
      "X  "
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where X won via middle column victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "OXO",
      " X ",
      " X "
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where X won via right column victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "OOX",
      "  X",
      "  X"
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where O won via left column victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "OXX",
      "OX ",
      "O  "
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where O won via middle column victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "XOX",
      " OX",
      " O "
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where O won via right column victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "XXO",
      " XO",
      "  O"
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where X won via top row victory") {
