  skip.test("Won games -> Finished game where O won via bottom row victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "XOX",
      " XX",
      "OOO"
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where X won via falling diagonal victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "XOO",
      " X ",
      "  X"
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where X won via rising diagonal victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "O X",
      "OX ",
      "X  "
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where O won via falling diagonal victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "OXX",
      "OOX",
      "X O"
    ])).toEqual("win")
  }

  skip.test("Won games -> Finished game where O won via rising diagonal victory") {
    Expect.value(StateOfTicTacToe.gamestate([
      "  O",
