  }

  skip.test("Invalid boards -> Invalid board: players kept playing after a win") {
    Expect.that {
      StateOfTicTacToe.gamestate([
      "XXX",
      "OOO",
      "XOX"
    ])
    }.abortsWith("Impossible board: game should have ended after the game was won")
  }
}
